migrations.sql:
-- Additive identity and authority. Legacy sessions remain until explicit invalidation.
CREATE TABLE authority_principals (id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('human','agent','connector','system')), human_id TEXT, state TEXT NOT NULL CHECK(state IN ('invited','active','removed','erased')), authentication_epoch INTEGER NOT NULL DEFAULT 1, initial_owner INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, version INTEGER NOT NULL DEFAULT 1);
INSERT INTO authority_principals(id,kind,human_id,state,created_at,updated_at) SELECT id,'human',id,CASE WHEN active=1 THEN 'active' ELSE 'removed' END,created_at,updated_at FROM operators;
CREATE TABLE authority_sessions (id TEXT PRIMARY KEY, principal_id TEXT NOT NULL REFERENCES authority_principals(id), token_hash TEXT NOT NULL UNIQUE, csrf_hash TEXT NOT NULL, authentication_epoch INTEGER NOT NULL, created_at INTEGER NOT NULL, last_seen_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, revoked_at INTEGER, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE authority_magic_tokens (id TEXT PRIMARY KEY, principal_id TEXT NOT NULL REFERENCES authority_principals(id), nonce_hash TEXT NOT NULL UNIQUE, return_to TEXT NOT NULL, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, consumed_at INTEGER, receipt_id TEXT, delivery_state TEXT);
CREATE TABLE authority_rate_limits (key_hash TEXT PRIMARY KEY, window_start INTEGER NOT NULL, count INTEGER NOT NULL);
CREATE TABLE authority_credentials (id TEXT PRIMARY KEY, principal_id TEXT NOT NULL REFERENCES authority_principals(id), token_hash TEXT NOT NULL UNIQUE, audience TEXT NOT NULL, scopes_json TEXT NOT NULL, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, revoked_at INTEGER, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE authority_policies (id TEXT PRIMARY KEY, app_id TEXT NOT NULL, name TEXT NOT NULL, rules_json TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE authority_memberships (principal_id TEXT NOT NULL REFERENCES authority_principals(id), app_id TEXT NOT NULL, policy_id TEXT NOT NULL REFERENCES authority_policies(id), legacy INTEGER NOT NULL DEFAULT 0, state TEXT NOT NULL DEFAULT 'active', version INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(principal_id,app_id));
CREATE TABLE authority_grants (id TEXT PRIMARY KEY, issuer_id TEXT NOT NULL REFERENCES authority_principals(id), delegate_id TEXT NOT NULL REFERENCES authority_principals(id), app_id TEXT NOT NULL, spec_json TEXT NOT NULL, impact_hash TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('proposed','active','revoked','expired')), version INTEGER NOT NULL DEFAULT 1, starts_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, revoked_at INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE authority_budgets (grant_id TEXT NOT NULL REFERENCES authority_grants(id), unit TEXT NOT NULL, ceiling TEXT NOT NULL, consumed TEXT NOT NULL DEFAULT '0', reserved TEXT NOT NULL DEFAULT '0', version INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(grant_id,unit));
CREATE TABLE authority_reservations (id TEXT PRIMARY KEY, grant_id TEXT NOT NULL REFERENCES authority_grants(id), grant_version INTEGER NOT NULL, command_id TEXT NOT NULL, unit TEXT NOT NULL, amount TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('reserved','consumed','released')), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(command_id,grant_id,unit));
CREATE INDEX authority_sessions_principal ON authority_sessions(principal_id);
CREATE INDEX authority_grants_delegate ON authority_grants(delegate_id,app_id,state);
CREATE INDEX authority_magic_expiry ON authority_magic_tokens(expires_at);
-- Plaintext legacy credentials cannot be safely retained. Preserve session history, revoke secrets.
UPDATE sessions SET revoked_at=COALESCE(revoked_at,unixepoch()*1000), token='retired:'||id;

-- Internal transport principal has no app memberships, grants or user-discoverable app.
INSERT INTO authority_principals(id,kind,human_id,state,authentication_epoch,initial_owner,created_at,updated_at,version) VALUES('00000000000000000000000001','system',NULL,'active',1,0,0,0,1);
ALTER TABLE authority_magic_tokens ADD COLUMN mail_input_hash TEXT;

ALTER TABLE authority_grants ADD COLUMN issuer_epoch INTEGER NOT NULL DEFAULT 0;
ALTER TABLE authority_grants ADD COLUMN delegate_epoch INTEGER NOT NULL DEFAULT 0;
ALTER TABLE authority_credentials ADD COLUMN authentication_epoch INTEGER NOT NULL DEFAULT 0;

ALTER TABLE authority_reservations ADD COLUMN app_id TEXT;
ALTER TABLE authority_reservations ADD COLUMN action TEXT;
ALTER TABLE authority_reservations ADD COLUMN owner_principal_id TEXT;
ALTER TABLE authority_reservations ADD COLUMN attempt_id TEXT;
ALTER TABLE authority_reservations ADD COLUMN input_hash TEXT;
ALTER TABLE authority_reservations ADD COLUMN binding_hash TEXT;
CREATE INDEX authority_reservations_attempt ON authority_reservations(attempt_id,command_id);

CREATE TABLE record_schemas (id TEXT PRIMARY KEY NOT NULL,app_id TEXT NOT NULL,version INTEGER NOT NULL,physical_revision TEXT NOT NULL,schema_json TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX record_schema_app ON record_schemas(app_id,id);
CREATE TABLE record_views (id TEXT PRIMARY KEY NOT NULL,app_id TEXT NOT NULL,entity_id TEXT NOT NULL,owner_id TEXT NOT NULL,version INTEGER NOT NULL,visibility TEXT NOT NULL,definition_json TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX record_views_app ON record_views(app_id,owner_id,id);
CREATE TABLE record_forms (id TEXT PRIMARY KEY NOT NULL,app_id TEXT NOT NULL,entity_id TEXT NOT NULL,version INTEGER NOT NULL,definition_json TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE record_previews (id TEXT PRIMARY KEY NOT NULL,app_id TEXT NOT NULL,entity_id TEXT NOT NULL,actor_id TEXT NOT NULL,input_hash TEXT NOT NULL,input_json TEXT NOT NULL,expected_json TEXT NOT NULL,expires_at TEXT NOT NULL,state TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE record_undo (id TEXT PRIMARY KEY NOT NULL,command_id TEXT NOT NULL,app_id TEXT NOT NULL,actor_id TEXT NOT NULL,inverse_json TEXT NOT NULL,expires_at TEXT NOT NULL,state TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);

CREATE TABLE command_admissions (
 command_id TEXT PRIMARY KEY NOT NULL, batch_nonce TEXT NOT NULL UNIQUE,
 actor_id TEXT NOT NULL, actor_kind TEXT NOT NULL, app_id TEXT NOT NULL,
 action TEXT NOT NULL, input_hash TEXT NOT NULL,
 state TEXT NOT NULL CHECK(state IN ('admitted','committed')),
 result_json TEXT, access_json TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE INDEX command_actor_app ON command_admissions(actor_id,app_id,created_at,command_id);
CREATE TABLE admission_assertions (nonce TEXT NOT NULL, sequence INTEGER NOT NULL, ok INTEGER NOT NULL CHECK(ok=1), PRIMARY KEY(nonce,sequence));
CREATE TABLE admission_audit (
 id TEXT PRIMARY KEY NOT NULL, command_id TEXT NOT NULL REFERENCES command_admissions(command_id),
 actor_id TEXT NOT NULL, actor_kind TEXT NOT NULL, app_id TEXT NOT NULL, action TEXT NOT NULL,
 subject_json TEXT, changes_json TEXT NOT NULL, source_ids_json TEXT NOT NULL, personal_refs_json TEXT NOT NULL, created_at TEXT NOT NULL
);
CREATE INDEX admission_audit_subject ON admission_audit(app_id,created_at,id);
CREATE TABLE admission_events (
 id TEXT PRIMARY KEY NOT NULL, command_id TEXT NOT NULL REFERENCES command_admissions(command_id), app_id TEXT NOT NULL,
 name TEXT NOT NULL, version INTEGER NOT NULL, subject_json TEXT, payload_json TEXT NOT NULL, cause_run_ids_json TEXT NOT NULL, created_at TEXT NOT NULL
);
CREATE INDEX admission_events_order ON admission_events(created_at,id);
CREATE TABLE admission_outbox (
 id TEXT PRIMARY KEY NOT NULL, command_id TEXT NOT NULL REFERENCES command_admissions(command_id), app_id TEXT NOT NULL,
 action TEXT NOT NULL, version INTEGER NOT NULL, input_json TEXT NOT NULL, not_before TEXT NOT NULL, grant_id TEXT, subject_json TEXT,
 source_release_id TEXT NOT NULL, cause_run_ids_json TEXT NOT NULL,
 state TEXT NOT NULL CHECK(state IN ('pending','dispatched','cancelled')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE INDEX admission_outbox_due ON admission_outbox(state,not_before,id);

CREATE TABLE admission_provenance_segments (
 command_id TEXT NOT NULL REFERENCES command_admissions(command_id) ON DELETE CASCADE,
 segment_index INTEGER NOT NULL CHECK(segment_index>=0),
 subjects_json TEXT NOT NULL,
 PRIMARY KEY(command_id,segment_index)
);

CREATE TABLE evidence_sources(id TEXT PRIMARY KEY, app_id TEXT NOT NULL, entity_id TEXT NOT NULL, record_id TEXT NOT NULL, field_ids TEXT NOT NULL, kind TEXT NOT NULL, connection_id TEXT, external_id TEXT, current_version INTEGER NOT NULL, created_at TEXT NOT NULL, erased_at TEXT, UNIQUE(connection_id,external_id));
CREATE TABLE evidence_source_versions(id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES evidence_sources(id), version INTEGER NOT NULL, sha256 TEXT NOT NULL, content TEXT, file_ids TEXT NOT NULL, effective_at TEXT, known_at TEXT NOT NULL, source_release_id TEXT, UNIQUE(source_id,version));
CREATE TABLE evidence_nodes(id TEXT PRIMARY KEY, app_id TEXT NOT NULL, kind TEXT NOT NULL, object_id TEXT NOT NULL, object_version INTEGER NOT NULL, created_at TEXT NOT NULL, invalidated_at TEXT, erased_at TEXT, UNIQUE(kind,object_id,object_version));
CREATE TABLE evidence_dependencies(id TEXT PRIMARY KEY, parent_id TEXT NOT NULL REFERENCES evidence_nodes(id), child_id TEXT NOT NULL REFERENCES evidence_nodes(id), UNIQUE(parent_id,child_id));
CREATE INDEX evidence_dependencies_parent ON evidence_dependencies(parent_id);
CREATE TABLE evidence_claims(id TEXT PRIMARY KEY, app_id TEXT NOT NULL, version INTEGER NOT NULL, subject_json TEXT, field_id TEXT, value_json TEXT, evidence_json TEXT NOT NULL, model_call_id TEXT, state TEXT NOT NULL, supersedes_id TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE evidence_proposals(id TEXT PRIMARY KEY, app_id TEXT NOT NULL, version INTEGER NOT NULL, action TEXT NOT NULL, subject_json TEXT NOT NULL, input_json TEXT, evidence_json TEXT NOT NULL, reason TEXT, expires_at TEXT NOT NULL, state TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE evidence_files(id TEXT PRIMARY KEY, app_id TEXT NOT NULL, entity_id TEXT NOT NULL, record_id TEXT NOT NULL, field_ids TEXT NOT NULL, filename TEXT NOT NULL, media_type TEXT NOT NULL, bytes INTEGER NOT NULL, sha256 TEXT NOT NULL, object_key TEXT NOT NULL UNIQUE, state TEXT NOT NULL, source_id TEXT, rejection TEXT, version INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE evidence_contexts(id TEXT PRIMARY KEY, app_id TEXT NOT NULL, principal_id TEXT NOT NULL, purpose TEXT NOT NULL, destination TEXT NOT NULL, profile_id TEXT NOT NULL, field_ids TEXT NOT NULL, source_refs TEXT NOT NULL, content TEXT, sha256 TEXT NOT NULL, expires_at TEXT NOT NULL, created_at TEXT NOT NULL, erased_at TEXT);
CREATE TABLE evidence_comments(id TEXT PRIMARY KEY, app_id TEXT NOT NULL, entity_id TEXT NOT NULL, record_id TEXT NOT NULL, author_id TEXT NOT NULL, author_kind TEXT NOT NULL, body TEXT, mentions_json TEXT NOT NULL, version INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT);
CREATE TABLE evidence_erasure_ledger(id TEXT PRIMARY KEY, subject_hash TEXT NOT NULL UNIQUE, subject_json TEXT NOT NULL, requested_at TEXT NOT NULL, completed_at TEXT, state TEXT NOT NULL, verification_json TEXT NOT NULL);
CREATE TABLE evidence_erasure_objects(id TEXT PRIMARY KEY, erasure_id TEXT NOT NULL REFERENCES evidence_erasure_ledger(id), object_key TEXT NOT NULL, deleted_at TEXT, UNIQUE(erasure_id,object_key));

CREATE TABLE portability_previews(id TEXT PRIMARY KEY, actor_id TEXT NOT NULL, app_id TEXT NOT NULL, entity_id TEXT NOT NULL, file_id TEXT NOT NULL, mapping_json TEXT NOT NULL, preview_json TEXT NOT NULL, input_hash TEXT NOT NULL, created_at TEXT NOT NULL, expires_at TEXT NOT NULL, committed_command_id TEXT);
CREATE TABLE portability_jobs(id TEXT PRIMARY KEY, kind TEXT NOT NULL, actor_id TEXT NOT NULL, state TEXT NOT NULL, manifest_json TEXT NOT NULL, progress_json TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, error TEXT);
CREATE TABLE portability_parts(job_id TEXT NOT NULL REFERENCES portability_jobs(id), part_index INTEGER NOT NULL, sha256 TEXT NOT NULL, content TEXT NOT NULL, PRIMARY KEY(job_id,part_index));
CREATE TABLE portability_fences(name TEXT PRIMARY KEY, job_id TEXT NOT NULL);
CREATE TABLE portability_steps(job_id TEXT PRIMARY KEY, progress_json TEXT NOT NULL);

CREATE TABLE evidence_staging (id TEXT PRIMARY KEY NOT NULL,app_id TEXT NOT NULL,owner_id TEXT NOT NULL,purpose TEXT NOT NULL CHECK(purpose IN ('import','source')),label TEXT NOT NULL DEFAULT '',version INTEGER NOT NULL DEFAULT 1,schema_version INTEGER NOT NULL DEFAULT 1,lifecycle TEXT NOT NULL DEFAULT 'active' CHECK(lifecycle IN ('active','erased')),created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX evidence_staging_owner ON evidence_staging(app_id,owner_id,lifecycle);
CREATE TABLE evidence_staging_files (id TEXT PRIMARY KEY NOT NULL,record_id TEXT NOT NULL REFERENCES evidence_staging(id),value TEXT NOT NULL REFERENCES evidence_files(id),position INTEGER NOT NULL);

CREATE TABLE execution_runs (
 id TEXT PRIMARY KEY, app_id TEXT NOT NULL, origin_command_id TEXT NOT NULL,
 request_json TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('queued','running','waiting','completed','failed','cancelled','partial','unknown','suppressed')),
 version INTEGER NOT NULL DEFAULT 1, control_epoch INTEGER NOT NULL, lease_owner TEXT, lease_expires_at TEXT, lease_epoch INTEGER NOT NULL DEFAULT 0,
 next_wake_at TEXT, retry_of TEXT REFERENCES execution_runs(id), first_failure_at TEXT, retry_count INTEGER NOT NULL DEFAULT 0,
 cause_identity TEXT NOT NULL, failure_json TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL,
 UNIQUE(origin_command_id)
);
CREATE INDEX execution_runs_due ON execution_runs(state,next_wake_at,id);
CREATE TABLE execution_attempts (
 id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES execution_runs(id), command_id TEXT NOT NULL, connection_id TEXT NOT NULL,
 action TEXT NOT NULL, provider TEXT NOT NULL, idempotency_key TEXT NOT NULL, input_hash TEXT NOT NULL, sealed_input TEXT,
 state TEXT NOT NULL CHECK(state IN ('prepared','dispatching','confirmed','refused','partial','unknown')), version INTEGER NOT NULL DEFAULT 1,
 lease_epoch INTEGER NOT NULL, reservation_ids_json TEXT NOT NULL, started_at TEXT, finished_at TEXT, first_possible_effect_at TEXT,
 external_id TEXT, receipt_id TEXT, next_check_at TEXT, unknown_deadline TEXT NOT NULL, custodian_id TEXT NOT NULL, escalated_at TEXT,
 created_at TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE INDEX execution_attempts_run ON execution_attempts(run_id,id);
CREATE INDEX execution_attempts_due ON execution_attempts(state,next_check_at,id);
CREATE TABLE execution_receipts (
 id TEXT PRIMARY KEY, attempt_id TEXT NOT NULL REFERENCES execution_attempts(id), provider TEXT NOT NULL, external_id TEXT,
 status TEXT NOT NULL CHECK(status IN ('confirmed','refused','partial','unknown')), evidence_file_id TEXT, observed_at TEXT NOT NULL,
 reconciled_at TEXT, method TEXT, message TEXT NOT NULL, result_json TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1
);
CREATE TABLE execution_run_attempts (run_id TEXT NOT NULL REFERENCES execution_runs(id),attempt_id TEXT NOT NULL REFERENCES execution_attempts(id),PRIMARY KEY(run_id,attempt_id));
CREATE TABLE execution_model_profiles (id TEXT PRIMARY KEY, app_id TEXT NOT NULL, profile_json TEXT NOT NULL,version INTEGER NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE execution_model_calls (id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES execution_runs(id),profile_id TEXT NOT NULL REFERENCES execution_model_profiles(id),call_json TEXT NOT NULL,version INTEGER NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);

CREATE TABLE provider_connections (id TEXT PRIMARY KEY,app_id TEXT NOT NULL,adapter_id TEXT NOT NULL,name TEXT NOT NULL,state TEXT NOT NULL,account_id TEXT NOT NULL,scopes_json TEXT NOT NULL,ownership_json TEXT NOT NULL,credential_ref TEXT,consent_scopes_json TEXT NOT NULL DEFAULT '[]',control_epoch INTEGER NOT NULL DEFAULT 0,version INTEGER NOT NULL DEFAULT 1,last_checked_at TEXT,last_sync_at TEXT,revoked_at TEXT,remote_revocation_state TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE connection_credentials (connection_id TEXT PRIMARY KEY REFERENCES provider_connections(id),sealed_json TEXT NOT NULL,expires_at TEXT,version INTEGER NOT NULL DEFAULT 1,refresh_owner TEXT,refresh_expires_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE connection_oauth_states (id TEXT PRIMARY KEY,connection_id TEXT NOT NULL REFERENCES provider_connections(id),actor_id TEXT NOT NULL,session_id TEXT NOT NULL,provider TEXT NOT NULL,state_hash TEXT NOT NULL UNIQUE,verifier_sealed TEXT NOT NULL,redirect_uri TEXT NOT NULL,return_to TEXT NOT NULL,expires_at TEXT NOT NULL,consumed_at TEXT,created_at TEXT NOT NULL);
CREATE TABLE connection_webhooks (id TEXT PRIMARY KEY,connection_id TEXT NOT NULL REFERENCES provider_connections(id),provider_event_id TEXT NOT NULL,body_hash TEXT NOT NULL,received_at TEXT NOT NULL,UNIQUE(connection_id,provider_event_id));
CREATE TABLE connection_mailbox_checkpoints (connection_id TEXT PRIMARY KEY REFERENCES provider_connections(id),scope_hash TEXT NOT NULL,page_token TEXT,observed_at TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1);

CREATE TABLE connection_jobs (
 id TEXT PRIMARY KEY, command_id TEXT NOT NULL UNIQUE, connection_id TEXT NOT NULL REFERENCES provider_connections(id),
 action TEXT NOT NULL, actor_json TEXT NOT NULL, state TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1,
 lease_owner TEXT, lease_expires_at TEXT, result_json TEXT, failure_json TEXT,
 created_at TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE INDEX connection_jobs_due ON connection_jobs(state,lease_expires_at);

CREATE TABLE execution_model_bindings (
 profile_id TEXT NOT NULL REFERENCES execution_model_profiles(id),principal_id TEXT NOT NULL,
 connection_id TEXT NOT NULL REFERENCES provider_connections(id),grant_id TEXT NOT NULL,grant_version INTEGER NOT NULL,
 custodian_id TEXT NOT NULL,max_output_tokens INTEGER NOT NULL,version INTEGER NOT NULL,
 created_at TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(profile_id,principal_id)
);

CREATE TABLE execution_collection_revisions(name TEXT PRIMARY KEY,revision INTEGER NOT NULL);
INSERT INTO execution_collection_revisions VALUES('connections',1),('attempts',1),('profiles',1),('calls',1);
CREATE TRIGGER execution_connections_insert AFTER INSERT ON provider_connections BEGIN UPDATE execution_collection_revisions SET revision=revision+1 WHERE name='connections'; END;
CREATE TRIGGER execution_connections_update AFTER UPDATE ON provider_connections BEGIN UPDATE execution_collection_revisions SET revision=revision+1 WHERE name='connections'; END;
CREATE TRIGGER execution_connections_delete AFTER DELETE ON provider_connections BEGIN UPDATE execution_collection_revisions SET revision=revision+1 WHERE name='connections'; END;
CREATE TRIGGER execution_attempts_insert AFTER INSERT ON execution_attempts BEGIN UPDATE execution_collection_revisions SET revision=revision+1 WHERE name='attempts'; END;
CREATE TRIGGER execution_attempts_update AFTER UPDATE ON execution_attempts BEGIN UPDATE execution_collection_revisions SET revision=revision+1 WHERE name='attempts'; END;
CREATE TRIGGER execution_attempts_delete AFTER DELETE ON execution_attempts BEGIN UPDATE execution_collection_revisions SET revision=revision+1 WHERE name='attempts'; END;
CREATE TRIGGER execution_profiles_insert AFTER INSERT ON execution_model_profiles BEGIN UPDATE execution_collection_revisions SET revision=revision+1 WHERE name='profiles'; END;
CREATE TRIGGER execution_profiles_update AFTER UPDATE ON execution_model_profiles BEGIN UPDATE execution_collection_revisions SET revision=revision+1 WHERE name='profiles'; END;
CREATE TRIGGER execution_profiles_delete AFTER DELETE ON execution_model_profiles BEGIN UPDATE execution_collection_revisions SET revision=revision+1 WHERE name='profiles'; END;
CREATE TRIGGER execution_calls_insert AFTER INSERT ON execution_model_calls BEGIN UPDATE execution_collection_revisions SET revision=revision+1 WHERE name='calls'; END;
CREATE TRIGGER execution_calls_update AFTER UPDATE ON execution_model_calls BEGIN UPDATE execution_collection_revisions SET revision=revision+1 WHERE name='calls'; END;
CREATE TRIGGER execution_calls_delete AFTER DELETE ON execution_model_calls BEGIN UPDATE execution_collection_revisions SET revision=revision+1 WHERE name='calls'; END;

-- Additive physical repair and business decision schema.
PRAGMA foreign_keys = ON;
CREATE TABLE repair_stores (id TEXT PRIMARY KEY NOT NULL,version INTEGER NOT NULL CHECK(version>0),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,lifecycle TEXT NOT NULL,schema_version INTEGER NOT NULL DEFAULT 1,name TEXT NOT NULL,location TEXT NOT NULL,contact_id TEXT NOT NULL,availability TEXT,active INTEGER NOT NULL CHECK(active IN (0,1)));
CREATE INDEX repair_stores_lifecycle ON repair_stores(lifecycle,id);
CREATE TABLE repair_assets (id TEXT PRIMARY KEY NOT NULL,version INTEGER NOT NULL CHECK(version>0),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,lifecycle TEXT NOT NULL,schema_version INTEGER NOT NULL DEFAULT 1,name TEXT NOT NULL,store_id TEXT NOT NULL REFERENCES repair_stores(id) ON DELETE RESTRICT,serial TEXT UNIQUE,trade TEXT NOT NULL,warranty_source_id TEXT,active INTEGER NOT NULL CHECK(active IN (0,1)));
CREATE INDEX repair_assets_lifecycle ON repair_assets(lifecycle,id);
CREATE INDEX repair_assets_store_id ON repair_assets(store_id,id);
CREATE TABLE repair_contractors (id TEXT PRIMARY KEY NOT NULL,version INTEGER NOT NULL CHECK(version>0),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,lifecycle TEXT NOT NULL,schema_version INTEGER NOT NULL DEFAULT 1,name TEXT NOT NULL,payee_id TEXT NOT NULL,email TEXT NOT NULL,active INTEGER NOT NULL CHECK(active IN (0,1)));
CREATE INDEX repair_contractors_lifecycle ON repair_contractors(lifecycle,id);
CREATE TABLE repair_credentials (id TEXT PRIMARY KEY NOT NULL,version INTEGER NOT NULL CHECK(version>0),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,lifecycle TEXT NOT NULL,schema_version INTEGER NOT NULL DEFAULT 1,contractor_id TEXT NOT NULL REFERENCES repair_contractors(id) ON DELETE RESTRICT,kind TEXT NOT NULL,trade TEXT NOT NULL,location TEXT NOT NULL,valid_from TEXT NOT NULL,valid_until TEXT NOT NULL,source_id TEXT NOT NULL,source_version TEXT NOT NULL,active INTEGER NOT NULL CHECK(active IN (0,1)));
CREATE INDEX repair_credentials_lifecycle ON repair_credentials(lifecycle,id);
CREATE INDEX repair_credentials_contractor_id ON repair_credentials(contractor_id,id);
CREATE TABLE repair_store_staff (id TEXT PRIMARY KEY NOT NULL,version INTEGER NOT NULL CHECK(version>0),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,lifecycle TEXT NOT NULL,schema_version INTEGER NOT NULL DEFAULT 1,store_id TEXT NOT NULL REFERENCES repair_stores(id) ON DELETE RESTRICT,principal_id TEXT NOT NULL,active INTEGER NOT NULL CHECK(active IN (0,1)));
CREATE INDEX repair_store_staff_lifecycle ON repair_store_staff(lifecycle,id);
CREATE INDEX repair_store_staff_store_id ON repair_store_staff(store_id,id);
CREATE TABLE repair_intakes (id TEXT PRIMARY KEY NOT NULL,version INTEGER NOT NULL CHECK(version>0),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,lifecycle TEXT NOT NULL,schema_version INTEGER NOT NULL DEFAULT 1,text TEXT NOT NULL,fingerprint TEXT NOT NULL UNIQUE,payload_hash TEXT NOT NULL,submitter_id TEXT NOT NULL,store_id TEXT REFERENCES repair_stores(id) ON DELETE RESTRICT,asset_id TEXT REFERENCES repair_assets(id) ON DELETE RESTRICT,source_ids TEXT NOT NULL,file_ids TEXT NOT NULL,candidates TEXT NOT NULL,question TEXT,case_id TEXT,work_order_id TEXT);
CREATE INDEX repair_intakes_lifecycle ON repair_intakes(lifecycle,id);
CREATE INDEX repair_intakes_store_id ON repair_intakes(store_id,id);
CREATE INDEX repair_intakes_asset_id ON repair_intakes(asset_id,id);
CREATE TABLE repair_jobs (id TEXT PRIMARY KEY NOT NULL,version INTEGER NOT NULL CHECK(version>0),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,lifecycle TEXT NOT NULL,schema_version INTEGER NOT NULL DEFAULT 1,intake_id TEXT NOT NULL REFERENCES repair_intakes(id) ON DELETE RESTRICT,objective TEXT NOT NULL,kind TEXT NOT NULL,case_id TEXT);
CREATE INDEX repair_jobs_lifecycle ON repair_jobs(lifecycle,id);
CREATE INDEX repair_jobs_intake_id ON repair_jobs(intake_id,id);
CREATE TABLE repair_work_orders (id TEXT PRIMARY KEY NOT NULL,version INTEGER NOT NULL CHECK(version>0),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,lifecycle TEXT NOT NULL,schema_version INTEGER NOT NULL DEFAULT 1,job_id TEXT NOT NULL REFERENCES repair_jobs(id) ON DELETE RESTRICT,intake_id TEXT NOT NULL UNIQUE REFERENCES repair_intakes(id) ON DELETE RESTRICT,asset_id TEXT NOT NULL REFERENCES repair_assets(id) ON DELETE RESTRICT,store_id TEXT NOT NULL REFERENCES repair_stores(id) ON DELETE RESTRICT,requester_id TEXT NOT NULL,contractor_id TEXT REFERENCES repair_contractors(id) ON DELETE RESTRICT,scope_hash TEXT NOT NULL,quote_id TEXT,completion_claim_id TEXT,acceptance_id TEXT,case_id TEXT);
CREATE INDEX repair_work_orders_lifecycle ON repair_work_orders(lifecycle,id);
CREATE INDEX repair_work_orders_job_id ON repair_work_orders(job_id,id);
CREATE INDEX repair_work_orders_intake_id ON repair_work_orders(intake_id,id);
CREATE INDEX repair_work_orders_asset_id ON repair_work_orders(asset_id,id);
CREATE INDEX repair_work_orders_store_id ON repair_work_orders(store_id,id);
CREATE INDEX repair_work_orders_contractor_id ON repair_work_orders(contractor_id,id);
CREATE TABLE repair_quotes (id TEXT PRIMARY KEY NOT NULL,version INTEGER NOT NULL CHECK(version>0),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,lifecycle TEXT NOT NULL,schema_version INTEGER NOT NULL DEFAULT 1,work_order_id TEXT NOT NULL REFERENCES repair_work_orders(id) ON DELETE RESTRICT,work_order_version TEXT NOT NULL,contractor_id TEXT NOT NULL REFERENCES repair_contractors(id) ON DELETE RESTRICT,contractor_version TEXT NOT NULL,payee_id TEXT NOT NULL,scope_hash TEXT NOT NULL,minor TEXT NOT NULL,currency TEXT NOT NULL,scale TEXT NOT NULL,tax_included INTEGER NOT NULL CHECK(tax_included IN (0,1)),line_items TEXT NOT NULL,exclusions TEXT NOT NULL,expires_at TEXT NOT NULL,evidence TEXT NOT NULL,offered_slot TEXT,approval_id TEXT,exact_hash TEXT NOT NULL);
CREATE INDEX repair_quotes_lifecycle ON repair_quotes(lifecycle,id);
CREATE INDEX repair_quotes_work_order_id ON repair_quotes(work_order_id,id);
CREATE INDEX repair_quotes_contractor_id ON repair_quotes(contractor_id,id);
CREATE TABLE repair_visits (id TEXT PRIMARY KEY NOT NULL,version INTEGER NOT NULL CHECK(version>0),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,lifecycle TEXT NOT NULL,schema_version INTEGER NOT NULL DEFAULT 1,work_order_id TEXT NOT NULL REFERENCES repair_work_orders(id) ON DELETE RESTRICT,quote_id TEXT NOT NULL REFERENCES repair_quotes(id) ON DELETE RESTRICT,start_at TEXT NOT NULL,end_at TEXT NOT NULL,attempt_id TEXT NOT NULL,receipt_id TEXT,external_id TEXT,contractor_accepted INTEGER NOT NULL CHECK(contractor_accepted IN (0,1)));
CREATE INDEX repair_visits_lifecycle ON repair_visits(lifecycle,id);
CREATE INDEX repair_visits_work_order_id ON repair_visits(work_order_id,id);
CREATE INDEX repair_visits_quote_id ON repair_visits(quote_id,id);
CREATE TABLE repair_completion_claims (id TEXT PRIMARY KEY NOT NULL,version INTEGER NOT NULL CHECK(version>0),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,lifecycle TEXT NOT NULL,schema_version INTEGER NOT NULL DEFAULT 1,work_order_id TEXT NOT NULL REFERENCES repair_work_orders(id) ON DELETE RESTRICT,visit_id TEXT NOT NULL REFERENCES repair_visits(id) ON DELETE RESTRICT,scope_hash TEXT NOT NULL,source_ids TEXT NOT NULL,evidence TEXT NOT NULL,author_id TEXT NOT NULL);
CREATE INDEX repair_completion_claims_lifecycle ON repair_completion_claims(lifecycle,id);
