CREATE TRIGGER launch_authority_removed AFTER UPDATE OF state ON authority_principals WHEN NEW.state<>'active' BEGIN UPDATE launch_analysis_requests SET state='Failed',error_code='forbidden',error_message='Requesting authority was removed' WHERE state IN ('Queued','Running') AND (actor_id=NEW.id OR json_extract(authority_json,'$.id')=NEW.id); UPDATE launch_analysis_requests SET authority_json=NULL WHERE actor_id=NEW.id OR json_extract(authority_json,'$.id')=NEW.id; UPDATE launch_automation_authorities SET principal_json=NULL WHERE json_extract(principal_json,'$.id')=NEW.id; END;
