 account_sid TEXT NOT NULL, from_value TEXT NOT NULL, sealed_json TEXT NOT NULL,
 version INTEGER NOT NULL, updated_at TEXT NOT NULL
);
CREATE TABLE sms_messages (
 id TEXT PRIMARY KEY, run_id TEXT NOT NULL, command_id TEXT NOT NULL,
 actor_id TEXT NOT NULL, app_id TEXT NOT NULL, entity_id TEXT NOT NULL, record_id TEXT NOT NULL,
 field_id TEXT NOT NULL, recipient TEXT NOT NULL, sender TEXT NOT NULL,
 provider_sid TEXT UNIQUE, status TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL
);
CREATE INDEX sms_messages_recipient ON sms_messages(recipient,created_at);
CREATE TABLE sms_suppressions (recipient_hash TEXT PRIMARY KEY, updated_at INTEGER NOT NULL);
CREATE TABLE sms_webhook_receipts (id TEXT PRIMARY KEY, received_at INTEGER NOT NULL);
CREATE TABLE sms_inbound_events (receipt_id TEXT PRIMARY KEY, recipient_hash TEXT NOT NULL, event TEXT NOT NULL, created_at INTEGER NOT NULL);

-- Preserve all R2 schedules and custody. Each object retains its own immutable
-- destination and sealed credential snapshot even after a schedule is changed.
ALTER TABLE warehouse_exports ADD COLUMN destination_json TEXT NOT NULL DEFAULT '{"kind":"r2"}';
ALTER TABLE warehouse_exports ADD COLUMN sealed_json TEXT;
ALTER TABLE warehouse_objects ADD COLUMN destination_json TEXT NOT NULL DEFAULT '{"kind":"r2"}';
ALTER TABLE warehouse_objects ADD COLUMN sealed_json TEXT;

-- The object key deterministically identifies a provider job/request. Schema
-- and row IDs exist before dispatch and survive unknown provider responses.
ALTER TABLE warehouse_objects ADD COLUMN metadata_json TEXT;
ALTER TABLE warehouse_objects ADD COLUMN dispatch_state TEXT NOT NULL DEFAULT 'prepared' CHECK(dispatch_state IN ('prepared','dispatching','confirmed'));

-- One owner-managed Slack app installation; people link without email inference.
CREATE TABLE slack_app_installation (
 id TEXT PRIMARY KEY CHECK(id='installation'), owner_id TEXT NOT NULL,
 client_id TEXT NOT NULL, sealed_json TEXT NOT NULL, bot_sealed_json TEXT,
 team_id TEXT, team_name TEXT, version INTEGER NOT NULL, updated_at TEXT NOT NULL
);
CREATE TABLE slack_app_oauth_states (
 state_hash TEXT PRIMARY KEY, actor_id TEXT NOT NULL, session_id TEXT NOT NULL,
 config_version INTEGER NOT NULL, expires_at INTEGER NOT NULL, consumed_at INTEGER
);
CREATE TABLE slack_app_link_codes (
 code_hash TEXT PRIMARY KEY, principal_id TEXT NOT NULL, authentication_epoch INTEGER NOT NULL,
 base_operator_id TEXT NOT NULL, base_operator_version INTEGER NOT NULL,
 expires_at INTEGER NOT NULL, consumed_at INTEGER
);
CREATE TABLE slack_app_links (
 team_id TEXT NOT NULL, slack_user_id TEXT NOT NULL, principal_id TEXT NOT NULL,
 authentication_epoch INTEGER NOT NULL, base_operator_id TEXT NOT NULL,
 base_operator_version INTEGER NOT NULL, created_at INTEGER NOT NULL,
 PRIMARY KEY(team_id,slack_user_id), UNIQUE(team_id,principal_id)
);
CREATE TABLE slack_app_unfurl_fields (
 app_id TEXT NOT NULL, entity_id TEXT NOT NULL, owner_id TEXT NOT NULL,
 fields_json TEXT NOT NULL, version INTEGER NOT NULL, PRIMARY KEY(app_id,entity_id)
);
CREATE TABLE slack_app_actions (
 id TEXT PRIMARY KEY, run_id TEXT NOT NULL, author_id TEXT NOT NULL,
 app_id TEXT NOT NULL, entity_id TEXT NOT NULL, record_id TEXT NOT NULL,
 record_version INTEGER NOT NULL, field_id TEXT NOT NULL, approve_json TEXT NOT NULL,
 reject_json TEXT NOT NULL, team_id TEXT NOT NULL, channel_id TEXT NOT NULL,
 config_version INTEGER NOT NULL, delivery_state TEXT NOT NULL,
 choice_state TEXT NOT NULL, message_ts TEXT, created_at INTEGER NOT NULL,
 applied_at INTEGER, applied_by TEXT
);
CREATE INDEX slack_app_actions_record ON slack_app_actions(app_id,entity_id,record_id);
CREATE TABLE slack_app_webhook_receipts (id TEXT PRIMARY KEY, received_at INTEGER NOT NULL);

-- Schema deletions share the existing Trash clock, authority and maintenance path.
ALTER TABLE record_trash ADD COLUMN kind TEXT NOT NULL DEFAULT 'record' CHECK(kind IN ('record','field','table'));
ALTER TABLE record_trash ADD COLUMN detail_json TEXT NOT NULL DEFAULT '{}';
CREATE INDEX record_trash_kind_expiry ON record_trash(kind,expires_at);

-- Preserve provider refusals and owner review of replies with no safe record attribution.
ALTER TABLE sms_messages ADD COLUMN provider_error_json TEXT;
ALTER TABLE sms_inbound_events ADD COLUMN sender_mask TEXT;
ALTER TABLE sms_inbound_events ADD COLUMN body TEXT;
ALTER TABLE sms_inbound_events ADD COLUMN unattributed INTEGER NOT NULL DEFAULT 0 CHECK(unattributed IN (0,1));
CREATE INDEX sms_inbound_review ON sms_inbound_events(unattributed,created_at,receipt_id);

-- Metadata-only custody for read exports that have no command admission.
CREATE TABLE operation_audit (
 id TEXT PRIMARY KEY NOT NULL,
 actor_id TEXT,
 app_id TEXT,
 action TEXT NOT NULL,
 feature TEXT,
 created_at TEXT NOT NULL
);
CREATE INDEX operation_audit_time ON operation_audit(created_at,id);
CREATE INDEX operation_audit_actor ON operation_audit(actor_id,created_at);

-- Multipart and resumable custody survives a Worker interruption. Session
-- capabilities are sealed; archive export removes all live transfer state.
ALTER TABLE warehouse_objects ADD COLUMN transfer_json TEXT NOT NULL DEFAULT '{}';
ALTER TABLE warehouse_exports ADD COLUMN running_started_at TEXT;
ALTER TABLE warehouse_exports ADD COLUMN running_at TEXT;
ALTER TABLE warehouse_exports ADD COLUMN running_slot TEXT;
ALTER TABLE warehouse_exports ADD COLUMN running_revision INTEGER;

-- One explicitly selected chat app; switching requires fresh provider consent.
ALTER TABLE slack_app_installation ADD COLUMN provider TEXT NOT NULL DEFAULT 'slack' CHECK(provider IN ('slack','nook','teams'));
ALTER TABLE slack_app_installation ADD COLUMN api_origin TEXT;

-- A removed/recreated installation must never revive an old external card even
-- when its integer configuration version and workspace ID happen to match.
ALTER TABLE slack_app_installation ADD COLUMN instance_id TEXT;
UPDATE slack_app_installation SET instance_id=lower(hex(randomblob(16))) WHERE id='installation';
-- Legacy cards have no provable installation binding. Leave them NULL so they
-- refuse rather than guessing from a reusable workspace/version pair.
ALTER TABLE slack_app_actions ADD COLUMN installation_instance TEXT;

-- Old pending consent states require a fresh installation attempt.
ALTER TABLE slack_app_oauth_states ADD COLUMN installation_instance TEXT;

ALTER TABLE slack_app_link_codes ADD COLUMN installation_instance TEXT;

-- Expand one legacy app into independently managed provider installations.
-- Keep credential ciphertext, installation instance, cards, links and consent intact.
CREATE TABLE slack_app_installation_next (
 id TEXT PRIMARY KEY CHECK(id IN ('slack','teams','nook')), owner_id TEXT NOT NULL,
 client_id TEXT NOT NULL, sealed_json TEXT NOT NULL, bot_sealed_json TEXT,
 team_id TEXT, team_name TEXT, version INTEGER NOT NULL, updated_at TEXT NOT NULL,
 provider TEXT NOT NULL UNIQUE CHECK(provider IN ('slack','teams','nook')),
 api_origin TEXT, instance_id TEXT, CHECK(id=provider)
);
INSERT INTO slack_app_installation_next
 SELECT provider,owner_id,client_id,sealed_json,bot_sealed_json,team_id,team_name,
 version,updated_at,provider,api_origin,instance_id FROM slack_app_installation;
DROP TABLE slack_app_installation;
ALTER TABLE slack_app_installation_next RENAME TO slack_app_installation;

-- Adopt Base's dependency-key custody contract without changing released rows.
-- Existing signing keys remain eligible for Base's atomic plaintext upgrade;
-- the installation secret stays in private settings and is never stored here.
ALTER TABLE rer_dependency_installation
 ADD COLUMN keys_sealed INTEGER NOT NULL DEFAULT 0 CHECK (keys_sealed IN (0, 1));
ALTER TABLE rer_dependency_installation
 ADD COLUMN key_ids TEXT NOT NULL DEFAULT '[]'
 CHECK (json_valid(key_ids) AND json_type(key_ids) = 'array');

-- Automatic recovery of an interrupted export run is finite. Each unsuccessful
-- execution is counted on the run's claim, with the retained objects seen at its
-- lease, and the slot at which recovery stopped. All are cleared with the claim.
-- No personal reference is added: counts and a schedule slot only.
ALTER TABLE warehouse_exports ADD COLUMN running_failures INTEGER NOT NULL DEFAULT 0;
ALTER TABLE warehouse_exports ADD COLUMN running_stalls INTEGER NOT NULL DEFAULT 0;
ALTER TABLE warehouse_exports ADD COLUMN running_objects INTEGER NOT NULL DEFAULT 0;
ALTER TABLE warehouse_exports ADD COLUMN running_stopped_slot TEXT;

-- Guest identity survives revocation and erasure so neither can grant wider access.
CREATE TABLE authority_guests (
 principal_id TEXT PRIMARY KEY REFERENCES authority_principals(id),
 app_id TEXT NOT NULL,
 invitation_delivered INTEGER NOT NULL DEFAULT 0,
 created_at INTEGER NOT NULL
);
CREATE TRIGGER cradle_guest_membership_insert BEFORE INSERT ON authority_memberships
 WHEN EXISTS(SELECT 1 FROM authority_guests WHERE principal_id=NEW.principal_id AND app_id<>NEW.app_id)
 BEGIN SELECT RAISE(ABORT,'guest_scope'); END;
CREATE TRIGGER cradle_guest_membership_update BEFORE UPDATE OF app_id,principal_id ON authority_memberships
 WHEN EXISTS(SELECT 1 FROM authority_guests WHERE principal_id=NEW.principal_id AND app_id<>NEW.app_id)
 BEGIN SELECT RAISE(ABORT,'guest_scope'); END;
CREATE TRIGGER cradle_guest_native_role BEFORE UPDATE OF role ON oa_operators
 WHEN NEW.role<>'member' AND EXISTS(SELECT 1 FROM cradle_base_operators m JOIN authority_guests g ON g.principal_id=m.principal_id WHERE m.base_id=NEW.id)
 BEGIN SELECT RAISE(ABORT,'guest_role'); END;
